package mod.cdv.tnpc.tactical;
import java.util.*;import com.tacz.guns.client.model.functional.MuzzleFlashRender;import com.tacz.guns.api.item.attachment.AttachmentType;import net.minecraft.world.item.ItemStack;
public class FlashChecks26 {static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}public static class Gun {public Map<Object,Object> attachments=new HashMap<>();public Map<Object,Object>getCurrentAttachmentItem(){return attachments;}public Object getCurrentGunItem(){return new Object();}}public static class Stack {public Mat last(){return new Mat();}}public static class Mat {public org.joml.Matrix3f normal(){return new org.joml.Matrix3f();}public org.joml.Matrix4f pose(){return new org.joml.Matrix4f();}}
 public static void main(String[]args){var world=new MotionChecks26.World();var npc=new MotionChecks26.Soldier(world);Gun gun=new Gun();MuzzleFlashRender functional=new MuzzleFlashRender(gun);Stack poses=new Stack();Object oldNormal=MuzzleFlashRender.muzzleFlashNormal,oldPose=MuzzleFlashRender.muzzleFlashPose;Client26.FIRES.put(npc,System.nanoTime());Client26.flash(functional,poses,7);ok(MuzzleFlashRender.draws==0,"player/other renderers unaffected outside NPC scope");Client26.begin(npc);Client26.flash(functional,poses,7);ok(MuzzleFlashRender.draws==1,"NPC muzzle is drawn on actual model-node scope");ok(MuzzleFlashRender.lastLight==15728880&&MuzzleFlashRender.lastOverlay==7,"flash emits light while retaining model overlay");ok(MuzzleFlashRender.usedPose!=oldPose,"physical muzzle pose supplied");ok(MuzzleFlashRender.muzzleFlashPose==oldPose&&MuzzleFlashRender.muzzleFlashNormal==oldNormal,"shared native muzzle state restored immediately");Client26.end();Client26.flash(functional,poses,0);ok(MuzzleFlashRender.draws==1,"render scope removed");Client26.begin(npc);Client26.FIRES.put(npc,System.nanoTime()-100_000_000L);Client26.flash(functional,poses,0);ok(MuzzleFlashRender.draws==1,"no lingering flash after shot");gun.attachments.put(AttachmentType.MUZZLE,new ItemStack("tacz:attachment",1));com.tacz.guns.api.TimelessAPI.suppressed=true;Client26.FIRES.put(npc,System.nanoTime());Client26.flash(functional,poses,0);ok(MuzzleFlashRender.draws==1,"native silence modifier respected");Client26.end();ok(Client26.WARN.isEmpty(),"client API paths did not silently fail");System.out.println("NPC_NATIVE_MUZZLE_POSE_TIMED_EMISSION_SUPPRESSOR_SCOPE_RESTORE_CHECKS="+checks);}}
